// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _tryTakeOver(address attacker) internal returns (address before, address after_) {
        before = c.owner();
        vm.prank(attacker);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", attacker));
        ok;
        after_ = c.owner();
    }

    function testRegression_attackerCannotSeizeOwnership() public {
        (address before, address after_) = _tryTakeOver(address(0xBEEF));
        assertEq(after_, before, "non-admin must not be able to change owner");
    }

    function testFuzz_attackerCannotSeizeOwnership(address attacker) public {
        vm.assume(attacker != address(0));
        vm.assume(attacker != address(this));
        vm.assume(attacker != address(c));
        vm.assume(uint160(attacker) > 9);
        (address before, address after_) = _tryTakeOver(attacker);
        assertEq(after_, before, "non-admin must not be able to change owner");
    }
}
